<?php
/** TPL-03 type hub. */
if (!defined('ABSPATH')) exit;
$term=get_queried_object();
if (!($term instanceof WP_Term)) { get_header(); get_footer(); return; }
$title=interworld_term_field('iw_tpl03_title',$term) ?: $term->name;
$subtitle=interworld_term_field('iw_tpl03_subtitle',$term);
$description=interworld_term_field('iw_tpl03_hero_description',$term) ?: term_description($term->term_id,'object_type');
$image=interworld_term_image_url($term);
$intro=interworld_term_field('iw_tpl03_intro',$term);
$groups=interworld_child_groups($term);
$page=max(1,(int)get_query_var('paged'));
$object_args=array('post_type'=>'interworld_object','post_status'=>'publish','posts_per_page'=>12,'paged'=>$page,'orderby'=>'title','order'=>'ASC','tax_query'=>array(array('taxonomy'=>'object_type','field'=>'term_id','terms'=>$term->term_id)));
$object_args=interworld_content_catalog_args($object_args);
$objects=new WP_Query($object_args);
$count=(int)$objects->found_posts;
$catalog_title=interworld_term_field('iw_tpl03_catalog_title',$term) ?: $term->name;
get_header(); ?>
<main class="interworld-category-page">
<section class="category-hero" id="definition"><?php if ($image) : ?><img class="category-hero-image" src="<?php echo esc_url($image); ?>" alt="" loading="eager"><?php endif; ?><div class="category-hero-content"><div class="category-breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">География Межмирья</a> · <?php echo esc_html($term->name); ?></div><div class="category-eyebrow">ЭНЦИКЛОПЕДИЯ МЕЖМИРЬЯ</div><h1><?php echo esc_html($title); ?></h1><?php if ($subtitle) : ?><div class="category-subtitle"><?php echo esc_html($subtitle); ?></div><?php endif; ?><?php if ($description) : ?><div class="category-hero-description"><?php echo wp_kses_post($description); ?></div><?php endif; ?><div class="category-stats"><div class="category-stat"><strong><?php echo esc_html($count); ?></strong><span><?php echo esc_html(interworld_tpl03_count_label($count,$term)); ?></span></div><?php if ($groups) : ?><div class="category-stat"><strong><?php echo esc_html(count($groups)); ?></strong><span>раздела</span></div><?php endif; ?></div></div></section>
<nav class="category-anchor-nav" aria-label="Навигация по странице"><div class="category-inner category-anchor-inner"><a href="#definition">Начало</a><?php if ($intro) : ?><a href="#about-category">Определение</a><?php endif; ?><?php if ($groups) : ?><a href="#system">Разделы</a><?php endif; ?><a href="#catalog"><?php echo esc_html($catalog_title); ?></a><?php interworld_tpl03_anchor_links($term); ?></div></nav>
<div class="category-inner"><?php interworld_content_catalog_form('Найти объект'); ?></div>
<?php if ($intro) : ?><section class="category-section" id="about-category"><div class="category-inner"><div class="category-intro-grid"><h2 class="category-intro-title"><?php echo esc_html(interworld_term_field('iw_tpl03_intro_title',$term) ?: 'Что такое ' . $title); ?></h2><div class="category-intro-copy"><?php echo wp_kses_post($intro); ?></div></div></div></section><?php endif; ?>
<?php if ($groups) : ?><section class="category-section system-section" id="system"><div class="category-inner"><div class="section-heading"><h2><?php echo esc_html(interworld_term_field('iw_tpl03_system_title',$term) ?: 'Разделы'); ?></h2><?php if (interworld_term_field('iw_tpl03_system_intro',$term)) : ?><p class="category-section-intro"><?php echo esc_html(interworld_term_field('iw_tpl03_system_intro',$term)); ?></p><?php endif; ?></div><div class="system-grid"><?php foreach ($groups as $group) : $url=get_term_link($group); if (is_wp_error($url)) continue; $preview=interworld_term_field('iw_tpl03_group_preview',$group) ?: $group->description; $group_image=interworld_term_field('iw_tpl03_group_image',$group); $group_image=$group_image ? wp_get_attachment_image_url((int)$group_image,'medium') : interworld_term_image_url($group); ?><a class="system-card" href="<?php echo esc_url($url); ?>"><div class="system-orb"><?php if ($group_image) : ?><img src="<?php echo esc_url($group_image); ?>" alt="" loading="lazy"><?php endif; ?></div><h3><?php echo esc_html(interworld_term_field('iw_tpl03_title',$group) ?: $group->name); ?></h3><?php if ($preview) : ?><p><?php echo esc_html(wp_strip_all_tags($preview)); ?></p><?php endif; ?><small><?php echo esc_html((int)$group->count . ' ' . interworld_tpl03_count_label((int)$group->count,$group)); ?></small></a><?php endforeach; ?></div></div></section><?php endif; ?>
<section class="category-section catalog-section" id="catalog"><div class="category-inner"><div class="section-heading"><h2><?php echo esc_html($catalog_title); ?></h2></div><?php if ($count) : ?><div class="category-card-grid"><?php foreach ($objects->posts as $object) : $id=$object->ID; $thumb=get_the_post_thumbnail_url($id,'large'); $number=function_exists('get_field') ? get_field('object_number',$id) : ''; $excerpt=get_the_excerpt($id); if (!$excerpt) $excerpt=interworld_content_value('object_short_definition',$id); ?><article class="category-card"><div class="category-card-image"><?php if ($thumb) : ?><img src="<?php echo esc_url($thumb); ?>" alt="" loading="lazy"><?php endif; ?></div><div class="category-card-body"><?php if ($number !== '' && $number !== null) : ?><div class="category-card-number"><?php echo esc_html($number); ?></div><?php endif; ?><h3 class="category-card-title"><?php echo esc_html(get_the_title($id)); ?></h3><?php if ($excerpt) : ?><p class="category-card-description"><?php echo esc_html($excerpt); ?></p><?php endif; ?><a class="category-card-link" href="<?php echo esc_url(get_permalink($id)); ?>" aria-label="Подробнее: <?php echo esc_attr(get_the_title($id)); ?>">Подробнее →</a></div></article><?php endforeach; ?></div><?php if ($objects->max_num_pages>1) : ?><nav class="pagination" aria-label="Страницы списка"><?php echo interworld_content_pagination($page,$objects->max_num_pages,'list'); ?></nav><?php endif; ?><?php else : ?><p><?php echo esc_html($catalog_title); ?> этого раздела пока не добавлены.</p><?php endif; ?></div></section>
<?php interworld_tpl03_render_sections($term); ?>
</main>
<?php wp_reset_postdata(); get_footer(); ?>
